import React, { useState } from 'react';

function App() {
  // Estados para controlar los campos del formulario
  const [nombre, setNombre] = useState('Empanada');
  const [categoria, setCategoria] = useState('Fritos');
  const [imagenUrl, setImagenUrl] = useState('https://www.bing.com/images/search?view=detailV2&ccid=PKW%2Ff');
  const [precioCosto, setPrecioCosto] = useState(1500);
  const [impuesto, setImpuesto] = useState('19'); // IVA 19%
  const [precioVenta, setPrecioVenta] = useState(2400);
  const [stock, setStock] = useState(20);

  // Cálculo dinámico del costo con IVA + Margen Sugerido (30%)
  const porcentajeIVA = parseFloat(impuesto) / 100;
  const costoConIVA = precioCosto * (1 + porcentajeIVA);
  const margenSugerido = costoConIVA * 1.30;

  // Formateador de moneda colombiana (COP)
  const formatearMoneda = (valor) => {
    return new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      minimumFractionDigits: 0
    }).format(valor);
  };

  const handleGuardar = (e) => {
    e.preventDefault();

    // Aquí irá tu petición fetch/axios hacia el backend de Java (localhost:8080)
    const nuevoProducto = {
      nombre,
      categoria,
      imagenUrl,
      precioCosto,
      impuesto,
      precioVenta,
      stock
    };

    console.log("Guardando en la base de datos:", nuevoProducto);
    // Ejemplo:
    // fetch('http://localhost:8080/api/productos', { ... })
    //   .catch(() => alert("Error al conectar con el servidor de Java."));
  };

  // Clases de estilo Tailwind para mantener la elegancia y limpieza visual
  const labelEstilo = "block text-xs text-[#9C8473] tracking-widest uppercase mb-2 ml-1 font-medium";
  const inputEstilo = "w-full bg-[#1A120C] text-[#F5F5F5] placeholder-[#5A4537] border border-[#4E3D32] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-[#E8C5C8] focus:ring-1 focus:ring-[#E8C5C8] transition-all duration-200";

  return (
    <div className="min-h-screen bg-[#130B07] py-12 px-4 flex flex-col justify-center items-center font-sans antialiased">

      {/* Botones de navegación superiores en armonía con el fondo */}
      <div className="w-full max-w-lg flex justify-between items-center mb-6 px-2">
        <button className="bg-[#261910] hover:bg-[#332216] text-[#E3CBB3] text-xs tracking-wider uppercase px-5 py-2.5 rounded-xl border border-[#3D291C] transition-all duration-200">
          📦 Ver Inventario
        </button>
        <button className="bg-[#2D1A1A] hover:bg-[#3D2323] text-[#E8C5C8] text-xs tracking-wider uppercase px-5 py-2.5 rounded-xl border border-[#4A2B2B] transition-all duration-200">
          🚪 Salir
        </button>
      </div>

      {/* Tarjeta Contenedora Principal (Inspirada en el diseño curvo editorial) */}
      <div className="w-full max-w-lg bg-[#1C120C] rounded-[2.5rem] p-8 md:p-10 shadow-2xl border border-[#2D1F16] relative overflow-hidden">

        {/* Detalle estético de luz ambiental de fondo */}
        <div className="absolute -top-12 -right-12 w-40 h-40 bg-[#E8C5C8] opacity-[0.03] rounded-full blur-2xl pointer-events-none"></div>
        <div className="absolute -bottom-12 -left-12 w-40 h-40 bg-[#C1D7C3] opacity-[0.02] rounded-full blur-2xl pointer-events-none"></div>

        <h2 className="text-xl md:text-2xl font-light text-[#E3CBB3] tracking-widest text-center mb-8 uppercase">
          Ingreso de Mercancía <span className="text-[#9C8473] font-normal block text-xs mt-1 lowercase tracking-normal">(distribuidor)</span>
        </h2>

        <form onSubmit={handleGuardar} className="space-y-5">

          {/* Nombre del Producto */}
          <div>
            <label className={labelEstilo}>Nombre del Producto</label>
            <input 
              type="text" 
              value={nombre} 
              onChange={(e) => setNombre(e.target.value)}
              placeholder="Ej. Empanada de carne" 
              className={inputEstilo} 
            />
          </div>

          {/* Categoría */}
          <div>
            <label className={labelEstilo}>Categoría</label>
            <input 
              type="text" 
              value={categoria} 
              onChange={(e) => setCategoria(e.target.value)}
              placeholder="Ej. Fritos" 
              className={inputEstilo} 
            />
          </div>

          {/* URL de la Imagen */}
          <div>
            <label className={labelEstilo}>Imagen (URL)</label>
            <input 
              type="text" 
              value={imagenUrl} 
              onChange={(e) => setImagenUrl(e.target.value)}
              placeholder="https://..." 
              className={inputEstilo} 
            />
          </div>

          {/* Fila: Precio Costo e Impuesto */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className={labelEstilo}>Precio Costo</label>
              <input 
                type="number" 
                value={precioCosto} 
                onChange={(e) => setPrecioCosto(Number(e.target.value))}
                placeholder="1500" 
                className={inputEstilo} 
              />
            </div>
            <div>
              <label className={labelEstilo}>Impuesto</label>
              <select 
                value={impuesto} 
                onChange={(e) => setImpuesto(e.target.value)}
                className={inputEstilo}
              >
                <option value="19">IVA 19% (General CO)</option>
                <option value="8">INC 8% (Consumo)</option>
                <option value="0">Exento de Impuesto</option>
              </select>
            </div>
          </div>

          {/* Tarjeta del Margen Sugerido (Integrada orgánicamente en verde pastel suave) */}
          <div className="bg-[#1F241F] rounded-2xl p-4 border border-[#2D382F] text-center transition-all duration-300">
            <p className="text-[11px] text-[#8BA48F] uppercase tracking-wider mb-1">
              Costo con IVA + Margen Sugerido (30%)
            </p>
            <span className="text-[#C1D7C3] font-semibold text-lg tracking-wide">
              {formatearMoneda(margenSugerido)}
            </span>
          </div>

          {/* Fila: Precio Venta y Stock Inicial */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className={labelEstilo}>Precio Venta</label>
              <input 
                type="number" 
                value={precioVenta} 
                onChange={(e) => setPrecioVenta(Number(e.target.value))}
                placeholder="2400" 
                className={inputEstilo} 
              />
            </div>
            <div>
              <label className={labelEstilo}>Stock Inicial</label>
              <input 
                type="number" 
                value={stock} 
                onChange={(e) => setStock(Number(e.target.value))}
                placeholder="20" 
                className={inputEstilo} 
              />
            </div>
          </div>

          {/* Botón Principal de Guardado (Rosa pastel viejo con tipografía premium) */}
          <button 
            type="submit" 
            className="w-full bg-[#E8C5C8] hover:bg-[#DFB4B8] text-[#130B07] font-semibold text-xs tracking-widest uppercase py-4 rounded-xl mt-4 transition-all duration-300 shadow-lg shadow-[#E8C5C8]/5 transform hover:-translate-y-0.5 active:translate-y-0"
          >
            Meter a la Base de Datos
          </button>
        </form>
      </div>
    </div>
  );
}

export default App;
